-- =====================================================================
-- Una empresa dueña en cada municipio y servicio (ADR-37): completa V21 donde ningún
-- prestador estaba registrado. Gas: distribuidora de GLP más cercana; los demás: el
-- municipio en prestación directa (Ley 142, art. 6) o, en áreas no municipalizadas, el
-- departamento. Generado por herramientas/generar-prestadores.py --complemento.
-- =====================================================================

-- Un municipio o departamento sin NIT conocido queda sin NIT (lo identifica su DIVIPOLA).
ALTER TABLE catalogo.empresas ALTER COLUMN nit DROP NOT NULL;

